-- Arbeitsrecht Berufsbildung > Betriebswirtschaftliche Grundlagen > Gewinnermittlung > Bilanzierung
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein IT-Betrieb bei der Bilanzierung Vermögenswerte und Schulden zum Stichtag aufstellen?', 2, '[{"text": "Ja", "correct": true, "because": "Bilanzierung zeigt Vermögen und Schulden zum Stichtag"}, {"text": "Nein", "correct": false, "because": "Das ist das Wesen der Bilanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Abschreibungen auf Server in der Bilanz eines IT-Betriebs zu berücksichtigen?', 2, '[{"text": "Ja", "correct": true, "because": "Abschreibungen mindern den Wert des Anlagevermögens"}, {"text": "Nein", "correct": false, "because": "Abschreibungen sind Teil der Bilanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch Bilanzierung den Gewinn des Geschäftsjahres ermitteln?', 2, '[{"text": "Ja", "correct": true, "because": "Bilanz dient als Grundlage für die Gewinnermittlung"}, {"text": "Nein", "correct": false, "because": "Bilanz und GuV ermitteln den Gewinn"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Bilanzierung eines IT-Betriebs Eigenkapital und Fremdkapital getrennt ausgewiesen werden?', 2, '[{"text": "Ja", "correct": true, "because": "Eigen- und Fremdkapital sind separate Bilanzpositionen"}, {"text": "Nein", "correct": false, "because": "Trennung ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Bilanzierung für kleine IT-Betriebe freiwillig?', 2, '[{"text": "Nein", "correct": true, "because": "Bilanzierung ist für bilanzierungspflichtige Unternehmen gesetzlich vorgeschrieben"}, {"text": "Ja", "correct": false, "because": "Pflicht je nach Rechtsform und Größe"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Bilanzierung für einen IT-Betrieb?', 2, '[{"text": "Darstellung von Vermögen und Schulden", "correct": true, "because": "Bilanz zeigt den finanziellen Zustand"}, {"text": "Nur Gewinnermittlung", "correct": false, "because": "Das ist Teil der GuV"}, {"text": "Steuererhöhung", "correct": false, "because": "Nicht das Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Seite der Bilanz zeigt das Vermögen eines IT-Betriebs?', 3, '[{"text": "Aktivseite", "correct": true, "because": "Aktivseite zeigt Vermögenswerte"}, {"text": "Passivseite", "correct": false, "because": "Passivseite zeigt Schulden und Eigenkapital"}, {"text": "Keine Seite", "correct": false, "because": "Aktivseite ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Position gehört auf die Passivseite der Bilanz eines IT-Betriebs?', 3, '[{"text": "Bankkredit", "correct": true, "because": "Fremdkapital wird auf der Passivseite ausgewiesen"}, {"text": "Firmenwagen", "correct": false, "because": "Das ist Anlagevermögen (Aktivseite)"}, {"text": "Bargeld", "correct": false, "because": "Das ist Umlaufvermögen (Aktivseite)"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Bilanzierung für einen IT-Betrieb?', 2, '[{"text": "Handelsgesetzbuch (HGB)", "correct": true, "because": "HGB legt Bilanzierungsregeln fest"}, {"text": "BBiG", "correct": false, "because": "BBiG regelt Ausbildung"}, {"text": "ArbSchG", "correct": false, "because": "ArbSchG regelt Arbeitsschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein IT-Betrieb bei der Bilanzierung Fehler macht?', 3, '[{"text": "Falsche Darstellung des finanziellen Zustands", "correct": true, "because": "Fehler verfälschen die Bilanz"}, {"text": "Keine Auswirkungen", "correct": false, "because": "Fehler haben Konsequenzen"}, {"text": "Automatische Korrektur", "correct": false, "because": "Fehler müssen manuell korrigiert werden"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Positionen gehören auf die Aktivseite der Bilanz eines IT-Betriebs?', 4, '[{"text": "Firmenwagen", "correct": true, "because": "Anlagevermögen"}, {"text": "Bankguthaben", "correct": true, "because": "Umlaufvermögen"}, {"text": "Bankkredit", "correct": false, "because": "Fremdkapital (Passivseite)"}, {"text": "Softwarelizenzen", "correct": true, "because": "Anlagevermögen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören auf die Passivseite der Bilanz eines IT-Betriebs?', 3, '[{"text": "Eigenkapital", "correct": true, "because": "Teil der Passivseite"}, {"text": "Bankkredit", "correct": true, "because": "Fremdkapital"}, {"text": "Büromöbel", "correct": false, "because": "Anlagevermögen (Aktivseite)"}, {"text": "Verbindlichkeiten aus Lieferungen", "correct": true, "because": "Fremdkapital"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen treffen auf die Bilanzierung eines IT-Betriebs zu?', 4, '[{"text": "Zeigt Vermögen und Schulden zum Stichtag", "correct": true, "because": "Definition der Bilanz"}, {"text": "Berücksichtigt Abschreibungen", "correct": true, "because": "Mindert Anlagevermögen"}, {"text": "Nur für Gewinnermittlung", "correct": false, "because": "Auch für Vermögensdarstellung"}, {"text": "Trennt Aktiva und Passiva", "correct": true, "because": "Bilanzstruktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Bilanzierung für einen IT-Betrieb?', 3, '[{"text": "Übersicht über Vermögen und Schulden", "correct": true, "because": "Hauptziel der Bilanz"}, {"text": "Grundlage für Gewinnermittlung", "correct": true, "because": "Mit GuV verbunden"}, {"text": "Keine Steuerpflicht", "correct": false, "because": "Bilanz beeinflusst Steuer nicht direkt"}, {"text": "Transparenz für Gläubiger", "correct": true, "because": "Zeigt finanzielle Lage"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört nicht zur Bilanzierung eines IT-Betriebs?', 3, '[{"text": "Vermögenswerte", "correct": false, "because": "Teil der Aktivseite"}, {"text": "Schulden", "correct": false, "because": "Teil der Passivseite"}, {"text": "Tägliche Umsätze", "correct": true, "because": "Das ist Teil der GuV, nicht der Bilanz"}, {"text": "Eigenkapital", "correct": false, "because": "Teil der Passivseite"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Bilanz zeigt Vermögen und Schulden eines IT-Betriebs. b) Abschreibungen werden nicht berücksichtigt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vermögen/Schulden ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Aktivseite zeigt das Vermögen eines IT-Betriebs. b) Eigenkapital wird auf der Aktivseite ausgewiesen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Aktivseite ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Bilanzierung ist für bilanzierungspflichtige IT-Betriebe gesetzlich vorgeschrieben. b) Tägliche Umsätze gehören in die Bilanz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pflicht ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Passivseite zeigt Fremdkapital eines IT-Betriebs. b) Bilanzierung dient nur der Steuererhöhung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fremdkapital ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Bilanzierung bietet Transparenz über die finanzielle Lage eines IT-Betriebs. b) Sie ist für alle IT-Betriebe freiwillig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Transparenz ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

